   !> emits `implicit copy(v, g, vbuf, f)` per launch and the threads race.
   subroutine pc2211(lo, hi, nseg, sOff, sA, sNB, sOA, sOB, sD, &
                      npair, sp_i, sp_j, sp_q, thresh, jfac, kfac, dsh, nbas, npp, nao, sh_l, ao_off, &
