                  f(2) = (3.0_dp*f(1) - bet)*(0.5_dp/tval)
                  f(3) = (5.0_dp*f(2) - bet)*(0.5_dp/tval)
                  f(4) = (7.0_dp*f(3) - bet)*(0.5_dp/tval)
                  f(5) = (9.0_dp*f(4) - bet)*(0.5_dp/tval)
                  f(6) = (11.0_dp*f(5) - bet)*(0.5_dp/tval)
               else
